// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Seller contact from car page: name, address, email, phone
// Flo: bonbanh and carmudi name comes from the label pass > carpla shop name and address sit around Xem cua hang and the posted line > oto name and phone follow Tin cung nguoi ban > tinbanxe name sits above Dia chi > chotot address follows Chat > email and second phone are scanned in the description > short text = first 160 bytes of the description
// I/O: a parsed Carz + its text lines (caller) > fills cnam, cadd, cmai, cph2, cdes, phon (when empty), sell; related-car cards further down the page are never read
// ===================================================================
const std = @import("std"); const typz = @import("pa-carz-type.zig"); const norm = @import("pa-carz-norm.zig"); const labl = @import("pa-carz-labl.zig"); const help = @import("pa-carz-help.zig");
const Carz = typz.Carz;
const DLER = [_][]const u8{ "showroom", "salon", "auto", "đại lý", "công ty", "cửa hàng", "motor", "ô tô", "car", "group", "trading", "dealer", "cty", "thaco", "oto" };
fn findLine(lins: []const []const u8, text: []const u8) ?usize { for (lins, 0..) |line, indx| { if (std.ascii.eqlIgnoreCase(line, text)) return indx; } return null; }
fn nameOkay(line: []const u8) bool { return line.len >= 2 and line.len <= 60 and labl.labeFind(labl.lablSpli(line).labl) == .none and std.mem.indexOf(u8, line, "://") == null; }
fn phonLike(line: []const u8) bool { var buff: [16]u8 = undefined; const phon = norm.normPhon(line, &buff); return phon.digi.len >= 9 and line.len <= 20; }
fn dealWord(name: []const u8) bool { for (DLER) |kwrd| { if (norm.hasz(name, kwrd)) return true; } return false; }
pub fn emaiFind(aren: std.mem.Allocator, body: []const u8, site: []const u8) ![]const u8 { var posi: usize = 0; while (std.mem.indexOfScalarPos(u8, body, posi, '@')) |atzz| { posi = atzz + 1; var star = atzz; while (star > 0 and (std.ascii.isAlphanumeric(body[star - 1]) or body[star - 1] == '.' or body[star - 1] == '_' or body[star - 1] == '-' or body[star - 1] == '+')) star -= 1; var endz = atzz + 1; while (endz < body.len and (std.ascii.isAlphanumeric(body[endz]) or body[endz] == '.' or body[endz] == '-')) endz += 1; while (endz > atzz + 1 and body[endz - 1] == '.') endz -= 1; if (star == atzz or endz <= atzz + 3) continue; const domn = body[atzz + 1 .. endz]; if (std.mem.indexOfScalar(u8, domn, '.') == null) continue; if (norm.hasz(site, domn) or norm.hasz(domn, site)) continue; return aren.dupe(u8, body[star..endz]); } return ""; }
fn phonSeco(aren: std.mem.Allocator, body: []const u8, firs: []const u8) ![]const u8 { var buff: [16]u8 = undefined; const fdig = norm.normPhon(firs, &buff).digi; var posi: usize = 0; while (posi < body.len) : (posi += 1) { if (body[posi] != '0' or (posi > 0 and std.ascii.isDigit(body[posi - 1]))) continue; var digs: [12]u8 = undefined; var cntz: usize = 0; var jdxz = posi; while (jdxz < body.len and cntz < 11) : (jdxz += 1) { const bytz = body[jdxz]; if (std.ascii.isDigit(bytz)) { digs[cntz] = bytz; cntz += 1; } else if (bytz != '.' and bytz != ' ' and bytz != '-') break; } if (cntz == 10 and !std.mem.eql(u8, digs[0..cntz], fdig) and !(jdxz < body.len and std.ascii.isDigit(body[jdxz]))) return aren.dupe(u8, digs[0..cntz]); } return ""; }
fn brieOfzz(aren: std.mem.Allocator, text: []const u8) ![]const u8 { if (text.len <= 160) return text; var endz: usize = 160; while (endz > 100 and text[endz] != ' ') endz -= 1; return aren.dupe(u8, text[0..endz]); }
pub fn contFind(aren: std.mem.Allocator, carz: *Carz, lins: []const []const u8, rawt: []const u8) !void { const site = carz.site;
    if (std.mem.eql(u8, site, "carpla.vn")) { if (findLine(lins, "Xem cửa hàng")) |indx| { if (indx >= 2 and nameOkay(lins[indx - 2])) carz.cnam = lins[indx - 2]; } for (lins, 0..) |line, indx| { if (indx > 0 and std.mem.startsWith(u8, line, "Đăng ") and std.mem.indexOfScalar(u8, lins[indx - 1], ',') != null) { carz.cadd = lins[indx - 1]; break; } } if (carz.cnam.len > 0 and carz.sell.len == 0) { carz.sell = "dealer"; carz.shop = carz.cnam; } }
    if (std.mem.eql(u8, site, "oto.com.vn")) { if (findLine(lins, "Tin cùng người bán")) |indx| { if (indx + 2 < lins.len and nameOkay(lins[indx + 1]) and !phonLike(lins[indx + 1])) { carz.cnam = lins[indx + 1]; if (phonLike(lins[indx + 2]) and carz.phon.len == 0) carz.phon = lins[indx + 2]; } } }
    if (std.mem.eql(u8, site, "tinbanxe.vn")) { for (lins, 0..) |line, indx| { if (indx > 300) break; const spli = labl.lablSpli(line); if (std.ascii.eqlIgnoreCase(spli.labl, "Địa chỉ") and spli.rest.len > 0) { carz.cadd = spli.rest; if (indx > 0 and nameOkay(lins[indx - 1])) { carz.cnam = lins[indx - 1]; if (std.mem.endsWith(u8, carz.text, carz.cnam)) carz.text = std.mem.trimEnd(u8, carz.text[0 .. carz.text.len - carz.cnam.len], " "); } break; } } }
    if (std.mem.eql(u8, site, "bonbanh.com")) { for (lins, 0..) |line, indx| { if (indx > 300) break; const spli = labl.lablSpli(line); if (std.ascii.eqlIgnoreCase(spli.labl, "Địa chỉ") and spli.rest.len > 0) { carz.cadd = spli.rest; break; } } }
    if (std.mem.eql(u8, site, "xe.chotot.com")) { if (findLine(lins, "Chat")) |indx| { if (indx + 1 < lins.len and std.mem.indexOfScalar(u8, lins[indx + 1], ',') != null) carz.cadd = lins[indx + 1]; } }
    carz.cmai = try emaiFind(aren, rawt, site); carz.cph2 = try phonSeco(aren, rawt, carz.phon); carz.cdes = try brieOfzz(aren, carz.text);
    if (carz.cnam.len > 0 and carz.sell.len == 0) carz.sell = if (dealWord(carz.cnam)) "dealer" else "private"; if (std.mem.eql(u8, carz.sell, "dealer") and carz.shop.len == 0) carz.shop = carz.cnam; }
